CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.role',true),'') $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('aal',current_setting('request.jwt.claim.aal',true),'email',current_setting('request.jwt.claim.email',true)) $$;
CREATE TYPE public.app_role AS ENUM('admin','user');
CREATE TABLE auth.users(id uuid primary key,email text,email_confirmed_at timestamptz);
CREATE TABLE public.user_roles(user_id uuid,role app_role);
CREATE TABLE public.sap_user_emails(user_key text,email text);
CREATE TABLE public.audit_log(actor_id uuid,actor_email text,action text,entity_type text,entity_id text,details jsonb);
CREATE TABLE public.synthetic_documents(id integer,user_id uuid,amount integer);
CREATE TABLE storage.objects(id integer,owner_id uuid,bucket_id text);
CREATE FUNCTION public.has_role(_user_id uuid,_role app_role) RETURNS boolean LANGUAGE sql SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) AND (_role<>'admin' OR auth.uid() IS NULL OR auth.uid()<>_user_id OR auth.jwt()->>'aal'='aal2') $$;
CREATE FUNCTION public.current_auth_email() RETURNS text LANGUAGE sql AS $$ SELECT current_setting('request.jwt.claim.email',true) $$;
CREATE FUNCTION public.is_impersonating(_user_id uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION public.canonical_user_key(t text) RETURNS text LANGUAGE sql AS $$ SELECT replace(split_part(lower(t),'@',1),'.','') $$;
CREATE FUNCTION public.get_nf_entrada_cache_by_po(_company_db text,_po_doc_entry integer) RETURNS TABLE(doc_entry integer) LANGUAGE sql SECURITY DEFINER AS $$ SELECT id FROM public.synthetic_documents $$;
CREATE FUNCTION public.get_system_activity(_hours integer) RETURNS TABLE(metric text,value bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN RETURN QUERY SELECT 'documents'::text,count(*) FROM public.synthetic_documents; END; $$;
GRANT USAGE ON SCHEMA public,auth,storage TO anon,authenticated,service_role;
GRANT SELECT ON public.synthetic_documents TO authenticated;
CREATE POLICY synthetic_owner ON public.synthetic_documents FOR SELECT TO authenticated USING(auth.uid()=user_id);
GRANT SELECT ON storage.objects TO authenticated;
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE POLICY storage_owner ON storage.objects FOR SELECT TO authenticated USING(auth.uid()=owner_id);
